    struct entry { char const* name; char const* doc; };
    inline entry const sDocs[] =
    {
        { "", "\nAn XML-RPC client interface for Python.\n\nThe marshalling and response parser code can also be used to\nimplement XML-RPC servers.\n\nExported exceptions:\n\n  Error          Base class for client errors\n  ProtocolError  Indicates an HTTP protocol error\n  ResponseError  Indicates a broken response package\n  Fault          Indicates an XML-RPC fault package\n\nExported classes:\n\n  ServerProxy    Represents a logical connection to an XML-RPC server\n\n  MultiCall      Executor of boxcared xmlrpc requests\n  DateTime       dateTime wrapper for an ISO 8601 string or time tuple or\n                 localtime integer value to generate a \"dateTime.iso8601\"\n                 XML-RPC value\n  Binary         binary data wrapper\n\n  Marshaller     Generate an XML-RPC params chunk from a Python data structure\n  Unmarshaller   Unmarshal an XML-RPC response from incoming XML event message\n  Transport      Handles an HTTP transaction to an XML-RPC server\n  SafeTransport  Handles an HTTPS transaction to an XML-RPC server\n\nExported constants:\n\n  (none)\n\nExported functions:\n\n  getparser      Create instance of the fastest available parser & attach\n                 to an unmarshalling object\n  dumps          Convert an argument tuple or a Fault instance to an XML-RPC\n                 request (or response, if the methodresponse option is used).\n  loads          Convert an XML-RPC packet to unmarshalled data plus a method\n                 name (None if not present).\n" },
        { "Binary", "Wrapper for binary data." },
        { "DateTime", "DateTime wrapper for an ISO 8601 string or time tuple or\nlocaltime integer value to generate 'dateTime.iso8601' XML-RPC\nvalue.\n" },
        { "Error", "Base class for client errors." },
        { "Fault", "Indicates an XML-RPC fault package." },
        { "GzipDecodedResponse", "a file-like object to decode a response encoded with the gzip\nmethod, as described in RFC 1952.\n" },
        { "Marshaller", "Generate an XML-RPC params chunk from a Python data structure.\n\nCreate a Marshaller instance for each set of parameters, and use\nthe \"dumps\" method to convert your data (represented as a tuple)\nto an XML-RPC params chunk.  To write a fault response, pass a\nFault instance instead.  You may prefer to use the \"dumps\" module\nfunction for this purpose.\n" },
        { "MultiCall", "server -> an object used to boxcar method calls\n\nserver should be a ServerProxy object.\n\nMethods can be added to the MultiCall using normal\nmethod call syntax e.g.:\n\nmulticall = MultiCall(server_proxy)\nmulticall.add(2,3)\nmulticall.get_address(\"Guido\")\n\nTo execute the multicall, call the MultiCall object e.g.:\n\nadd_result, address = multicall()\n" },
        { "MultiCallIterator", "Iterates over the results of a multicall. Exceptions are\nraised in response to xmlrpc faults." },
        { "ProtocolError", "Indicates an HTTP protocol error." },
        { "ResponseError", "Indicates a broken response package." },
        { "SafeTransport", "Handles an HTTPS transaction to an XML-RPC server." },
        { "ServerProxy", "uri [,options] -> a logical connection to an XML-RPC server\n\nuri is the connection point on the server, given as\nscheme://host/target.\n\nThe standard implementation always supports the \"http\" scheme.  If\nSSL socket support is available (Python 2.0), it also supports\n\"https\".\n\nIf the target part and the slash preceding it are both omitted,\n\"/RPC2\" is assumed.\n\nThe following options can be given as keyword arguments:\n\n    transport: a transport factory\n    encoding: the request encoding (default is UTF-8)\n\nAll 8-bit strings passed to the server proxy are assumed to use\nthe given encoding.\n" },
        { "ServerProxy.__call__", "A workaround to get special attributes on the ServerProxy\nwithout interfering with the magic __getattr__\n" },
        { "Transport", "Handles an HTTP transaction to an XML-RPC server." },
        { "Unmarshaller", "Unmarshal an XML-RPC response, based on incoming XML event\nmessages (start, data, end).  Call close() to get the resulting\ndata structure.\n\nNote that this reader is fairly tolerant, and gladly accepts bogus\nXML-RPC data without complaining (but not bogus XML).\n" },
        { "dumps", "data [,options] -> marshalled data\n\nConvert an argument tuple or a Fault instance to an XML-RPC\nrequest (or response, if the methodresponse option is used).\n\nIn addition to the data object, the following options can be given\nas keyword arguments:\n\n    methodname: the method name for a methodCall packet\n\n    methodresponse: true to create a methodResponse packet.\n    If this option is used with a tuple, the tuple must be\n    a singleton (i.e. it can contain only one element).\n\n    encoding: the packet encoding (default is UTF-8)\n\nAll byte strings in the data structure are assumed to use the\npacket encoding.  Unicode strings are automatically converted,\nwhere necessary.\n" },
        { "getparser", "getparser() -> parser, unmarshaller\n\nCreate an instance of the fastest available parser, and attach it\nto an unmarshalling object.  Return both objects.\n" },
        { "gzip_decode", "gzip encoded data -> unencoded data\n\nDecode data using the gzip content encoding as described in RFC 1952\n" },
        { "gzip_encode", "data -> gzip encoded data\n\nEncode data using the gzip content encoding as described in RFC 1952\n" },
        { "loads", "data -> unmarshalled data, method name\n\nConvert an XML-RPC packet to unmarshalled data plus a method\nname (None if not present).\n\nIf the XML-RPC packet represents a fault condition, this function\nraises a Fault exception.\n" },
    };
